package knn

// WEIGHT MODEL BY VARIABLE TYPE AND MISSION TYPE
// (port of pesos_mision.py, with the decision on the pending question applied)
//
// It does not use regional values, only:
//   (a) Mu[j]: the TYPE of variable j, a probability distribution over the
//       categories (each row sums to 1);
//   (b) d: the mission demand PROFILE (≥ 0, sum > 0, normalized automatically).
//
// F1  affinity   r_j = Σ_c μ_jc d_c = |μ_j||d| cos θ_j        (diagnostic)
// F2′ weight     w_j = Σ_c μ_jc d̃_c / n_c,   n_c = Σ_i μ_ic
//
// F2′ is F1 with the demand of each category distributed among its n_c
// variables. It answers the pending question from the README: the category receives
// exactly the weight requested by the mission, regardless of how many variables
// we measure from it.
//
// Derivation. Each variable j is divided into portions (j, c) with a priori mass
// μ_jc. We look for the distribution q that deviates the least from that a priori mass (minimum
// KL divergence) subject to each category receiving its demand:
//
//  min Σ q_jc ln(q_jc / μ_jc)   s.t.  Σ_j q_jc = d̃_c  ∀c
//  ∂L/∂q_jc = ln(q_jc/μ_jc) + 1 − λ_c = 0  ⇒  q_jc = μ_jc e^{λ_c − 1}
//  Σ_j q_jc = d̃_c  ⇒  e^{λ_c − 1} = d̃_c / n_c  ⇒  q_jc = μ_jc d̃_c / n_c
//
// KL is strictly convex, so the optimum is unique. w_j = Σ_c q_jc.
//
// Relation to F2/F3 from the README (softmax + β calibrated to N* = n e^{H(d)}/C):
// with balanced categories (n_c = n/C) and pure types,
// N_ef(F2′) = e^{H(d)} Π n_c^{d_c} = n e^{H(d)}/C = N*. F2′ achieves the same
// concentration objective without a free parameter: there is no β, bisection,
// BETA_MAX, or floor_applied.

import (
	"errors"
	"fmt"
	"math"
	"sort"
)

var Categories = []string{"GEO", "MEC", "VOL", "TER", "ENE", "ATM", "NAV"}

// GEO terrain geometry | MEC soil mechanics | VOL volatiles/chemistry/bio
// TER thermal | ENE energy/illumination | ATM atmosphere/wind | NAV navigation/comms

var Mu = map[string]map[string]float64{
	"slope":                    {"GEO": 1},
	"radar_roughness":          {"GEO": .7, "MEC": .3},
	"apparent_thermal_inertia": {"MEC": .5, "TER": .5},
	"soil_moisture":            {"MEC": .5, "VOL": .5},
	"visual_texture":           {"GEO": .5, "NAV": .5},
	"low_sun_shadows":          {"GEO": .6, "NAV": .4},
	"line_of_sight":            {"NAV": 1},
	"diurnal_thermal_range":    {"TER": 1},
	"dust_aerosols":            {"ATM": .5, "ENE": .5},
	"insolation":               {"ENE": .8, "TER": .2},
	"rock_abundance_pct":       {"GEO": .6, "MEC": .4},
	"grain_size_um":            {"MEC": 1},
	"angle_of_repose_deg":      {"MEC": 1},
	"depth_to_bedrock":         {"MEC": .8, "GEO": .2},
	"vrm_microrelief":          {"GEO": 1},
	"dielectric_constant":      {"VOL": .7, "MEC": .3},
	"salinity_wt_pct":          {"VOL": 1},
	"diffuse_ratio":            {"ENE": 1},
	"albedo":                   {"ENE": .5, "TER": .5},
	"vegetation_ndvi":          {"VOL": 1},
	"surface_pressure_kpa":     {"ATM": 1},
	"wind_typical_ms":          {"ATM": 1},
	"wind_gust_ms":             {"ATM": 1},
	"abrasive_mohs":            {"MEC": 1},

	"ground_ice_index": {"VOL": .7, "MEC": .3},
}

var Missions = map[string]map[string]float64{
	"rover":    {"GEO": .30, "MEC": .35, "VOL": .20, "NAV": .10, "ENE": .05},
	"edl":      {"GEO": .35, "ATM": .35, "NAV": .10, "MEC": .10, "ENE": .05, "TER": .05},
	"habitat":  {"TER": .20, "ENE": .20, "ATM": .15, "MEC": .15, "VOL": .15, "GEO": .10, "NAV": .05},
	"agua_bio": {"VOL": .50, "MEC": .20, "TER": .15, "GEO": .10, "ENE": .05},
}

var ErrUnknownFilter = errors.New("filtro desconocido")

type VariableWeight struct {
	Affinity float64 `json:"affinity"`
	Weight   float64 `json:"weight"`
	Factor   float64 `json:"factor"`
}

type WeightReport struct {
	Mission    string                    `json:"mission"`
	Profile    map[string]float64        `json:"profile"`
	NEf        float64                   `json:"nEf"`
	NStar      float64                   `json:"nStar"`
	AngleDeg   float64                   `json:"angleDeg"`
	NoAffinity bool                      `json:"noAffinity"`
	Variables  map[string]VariableWeight `json:"variables"`
}

func validateVector(vec map[string]float64, ok map[string]bool, name string, sumOne bool) error {
	keys := make([]string, 0, len(vec))
	for c := range vec {
		keys = append(keys, c)
	}
	sort.Strings(keys)
	s := 0.0
	for _, c := range keys {
		// Handle so typos ("GEOO") wont ignore, now raises error.
		if !ok[c] {
			return fmt.Errorf("%s: category unknown %q", name, c)
		}
		x := vec[c]
		if math.IsNaN(x) || math.IsInf(x, 0) || x < 0 {
			return fmt.Errorf("%s[%s]=%v: must be finite y >= 0", name, c, x)
		}
		s += x
	}
	if sumOne && math.Abs(s-1) > 1e-9 {
		return fmt.Errorf("%s: sum %v, must be 1", name, s)
	}
	if !sumOne && !(s > 0) {
		return fmt.Errorf("%s: sum 0, mission is not demanding nothing", name)
	}
	return nil
}

func validateModel(mu map[string]map[string]float64, profile map[string]float64, cats []string) error {
	ok := make(map[string]bool, len(cats))
	for _, c := range cats {
		if ok[c] {
			return errors.New("Duplicated categories")
		}
		ok[c] = true
	}
	if len(cats) == 0 {
		return errors.New("Empty Categorys")
	}
	if len(mu) == 0 {
		return errors.New("Mu has no vars")
	}
	for _, v := range sortedKeys(mu) {
		if err := validateVector(mu[v], ok, "Mu["+v+"]", true); err != nil {
			return err
		}
	}
	return validateVector(profile, ok, "Mision profile", false)
}

func sortedKeys[T any](m map[string]T) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func entropy(p []float64) float64 {
	h := 0.0
	for _, x := range p {
		if x > 0 {
			h -= x * math.Log(x)
		}
	}
	return h
}

func ComputeWeights(profile map[string]float64, mu map[string]map[string]float64, cats []string) (WeightReport, error) {
	if err := validateModel(mu, profile, cats); err != nil {
		return WeightReport{}, err
	}
	vars := sortedKeys(mu)
	n := len(vars)
	rep := WeightReport{Profile: map[string]float64{}, Variables: make(map[string]VariableWeight, n)}

	// n_c = Σ_j μ_jc.

	nc := map[string]float64{}
	for _, v := range vars {
		for _, c := range cats {
			nc[c] += mu[v][c]
		}
	}
	var used []string
	mass := 0.0
	for _, c := range cats {
		if nc[c] > 0 {
			used = append(used, c)
			mass += profile[c]
		}
	}

	w := make([]float64, n)
	if !(mass > 0) {

		for i, v := range vars {
			w[i] = 1 / float64(n)
			rep.Variables[v] = VariableWeight{Weight: w[i], Factor: 1}
		}
		rep.NoAffinity, rep.NEf, rep.NStar = true, float64(n), float64(n)
		rep.AngleDeg = 0
		return rep, nil
	}

	d := make([]float64, 0, len(used))
	for _, c := range used {
		rep.Profile[c] = profile[c] / mass
		d = append(d, rep.Profile[c])
	}

	for i, v := range vars {
		r, wi := 0.0, 0.0
		for _, c := range used {
			x := mu[v][c]
			r += x * rep.Profile[c]
			wi += x * rep.Profile[c] / nc[c]
		}
		w[i] = wi
		rep.Variables[v] = VariableWeight{Affinity: r, Weight: wi, Factor: float64(n) * wi}
	}

	rep.NEf = math.Exp(entropy(w))
	rep.NStar = float64(n) * math.Exp(entropy(d)) / float64(len(used))

	cos := 0.0
	for _, x := range w {
		cos += math.Sqrt(x / float64(n))
	}
	rep.AngleDeg = math.Acos(math.Min(1, cos)) * 180 / math.Pi
	return rep, nil
}

func (m *Model) validateFeatureMapping() error {
	shares := map[string]float64{}
	for _, f := range m.features {
		if _, ok := m.mu[f.MuVar]; !ok {
			return fmt.Errorf("Dimension %q points to %q, which is not in mu", f.Name, f.MuVar)
		}
		if !(f.Share > 0 && f.Share <= 1) {
			return fmt.Errorf("Dimension %q has share = %f outside from (0, 1]", f.Name, f.Share)
		}
		shares[f.MuVar] += f.Share
	}
	for _, v := range sortedKeys(m.mu) {
		if math.Abs(shares[v]-1) > 1e-12 {
			return fmt.Errorf(" %q Mu has a Share total %v (Must be 1; 0 = not in vector)", v, shares[v])
		}
	}
	return nil
}

var missionReports = func() map[string]WeightReport {
	out := make(map[string]WeightReport, len(Missions))
	for _, name := range sortedKeys(Missions) {
		rep, err := ComputeWeights(Missions[name], Mu, Categories)
		if err != nil {
			panic(fmt.Sprintf("knn: misión %s: %v", name, err))
		}
		rep.Mission = name
		out[name] = rep
	}
	return out
}()

func MissionNames() []string { return sortedKeys(Missions) }

func MissionReports() []WeightReport {
	out := make([]WeightReport, 0, len(missionReports))
	for _, k := range sortedKeys(missionReports) {
		out = append(out, missionReports[k])
	}
	return out
}

func (m *Model) expand(perVar map[string]float64, names []string) (Vector, error) {
	byName := make(map[string]feature, len(m.features))
	for _, f := range m.features {
		byName[f.Name] = f
	}
	w := make(Vector, len(names))
	for i, n := range names {
		f, ok := byName[n]
		if !ok {

			return nil, fmt.Errorf("Dimension %q is not in the model of weights", n)
		}
		w[i] = perVar[f.MuVar] * f.Share
	}
	return w, nil
}

func (m *Model) uniformPerVar() map[string]float64 {
	out := make(map[string]float64, len(m.mu))
	for v := range m.mu {
		out[v] = 1 / float64(len(m.mu))
	}
	return out
}

func reportPerVar(rep WeightReport) map[string]float64 {
	out := make(map[string]float64, len(rep.Variables))
	for v, x := range rep.Variables {
		out[v] = x.Weight
	}
	return out
}

func WeightsFor(filter string, names []string) (Vector, error) {
	if filter == "" {
		return Default.expand(Default.uniformPerVar(), names)
	}
	rep, ok := missionReports[filter]
	if !ok {
		return nil, ErrUnknownFilter
	}
	return Default.expand(reportPerVar(rep), names)
}package knn

// Model: the set of dimensions the KNN compares and the variable types (Mu)
// the weights are computed from.
//
// Default is the built-in model (26 dimensions, 25 Mu variables). NewModel adds
// user-defined variables on top of it (--own-regions): each one is a new Mu row
// (its type over the 7 categories) and a new dimension read from
// region.customVariables[name]. Nothing else changes: F2′, the projection to the
// terrestrial range, coverage and the breakdown work the same for any number of
// dimensions, so the built-in path and the custom path share all the code.
//
// Adding a variable to category c raises n_c, so the weight the mission gives c
// is shared among more variables (F2′: w_j = Σ_c μ_jc d̃_c / n_c). If the Earth
// catalog has no values for it, the dimension is missing for every candidate and
// coverage drops instead of the distance being invented.

import (
	"errors"
	"fmt"
	"regexp"

	"spaceapps/jsonParser"
)

// CustomVariable: a user-defined variable and its type (memberships sum to 1).
type CustomVariable struct {
	Name        string             `json:"name"`
	Label       string             `json:"label,omitempty"`
	Unit        string             `json:"unit,omitempty"`
	Memberships map[string]float64 `json:"memberships"`
}

// FeatureInfo describes one dimension for the frontend (GET /api/catalog).
type FeatureInfo struct {
	Name        string             `json:"name"`
	Group       string             `json:"group"` // core | audit | custom
	Variable    string             `json:"variable"`
	Share       float64            `json:"share"`
	Label       string             `json:"label,omitempty"`
	Unit        string             `json:"unit,omitempty"`
	Memberships map[string]float64 `json:"memberships"`
}

type Model struct {
	categories []string
	mu         map[string]map[string]float64
	features   []feature
	custom     map[string]CustomVariable
}

// Default: built-in model. Panics at start-up if the feature table and Mu disagree.
var Default = func() *Model {
	m, err := NewModel(nil)
	if err != nil {
		panic("knn: " + err.Error())
	}
	return m
}()

var customNameRe = regexp.MustCompile(`^[a-z][a-z0-9_]{0,47}$`)

// MaxCustomVariables bounds the size of a user model.
const MaxCustomVariables = 50

// NewModel: built-in variables plus the given custom ones (nil = built-in only).
func NewModel(custom []CustomVariable) (*Model, error) {
	if len(custom) > MaxCustomVariables {
		return nil, fmt.Errorf("variables: %d defined, max %d", len(custom), MaxCustomVariables)
	}
	m := &Model{
		categories: append([]string(nil), Categories...),
		mu:         make(map[string]map[string]float64, len(Mu)+len(custom)),
		features:   append([]feature(nil), features...),
		custom:     make(map[string]CustomVariable, len(custom)),
	}
	for v, row := range Mu {
		m.mu[v] = copyMap(row)
	}
	builtinDims := make(map[string]bool, len(features))
	for _, f := range features {
		builtinDims[f.Name] = true
	}
	okCat := make(map[string]bool, len(Categories))
	for _, c := range Categories {
		okCat[c] = true
	}
	for i, cv := range custom {
		path := fmt.Sprintf("variables[%d]", i)
		if !customNameRe.MatchString(cv.Name) {
			return nil, fmt.Errorf("%s.name %q: use lowercase letters, digits and _ (max 48), starting with a letter", path, cv.Name)
		}
		if _, seen := m.custom[cv.Name]; seen {
			return nil, fmt.Errorf("%s.name %q: defined twice", path, cv.Name)
		}
		if _, builtin := m.mu[cv.Name]; builtin || builtinDims[cv.Name] {
			return nil, fmt.Errorf("%s.name %q: collides with a built-in variable", path, cv.Name)
		}
		if err := validateVector(cv.Memberships, okCat, path+".memberships", true); err != nil {
			return nil, err
		}
		name := cv.Name
		m.mu[name] = copyMap(cv.Memberships)
		m.custom[name] = cv
		m.features = append(m.features, feature{
			Name: name, Group: "custom", MuVar: name, Share: 1,
			Get: func(r *jsonParser.Region) *float64 { return r.CustomVariables[name] },
		})
	}
	if err := m.validateFeatureMapping(); err != nil {
		return nil, err
	}
	return m, nil
}

func copyMap(in map[string]float64) map[string]float64 {
	out := make(map[string]float64, len(in))
	for k, v := range in {
		out[k] = v
	}
	return out
}

// IsCustomVariable reports whether name is a user-defined variable of this model.
func (m *Model) IsCustomVariable(name string) bool {
	_, ok := m.custom[name]
	return ok
}

// CustomVariables returns the user-defined variables, in definition (vector) order.
func (m *Model) CustomVariables() []CustomVariable {
	out := make([]CustomVariable, 0, len(m.custom))
	for _, f := range m.features {
		if f.Group == "custom" {
			out = append(out, m.custom[f.Name])
		}
	}
	return out
}

// Features describes every dimension of the model, in vector order.
func (m *Model) Features() []FeatureInfo {
	out := make([]FeatureInfo, len(m.features))
	for i, f := range m.features {
		fi := FeatureInfo{Name: f.Name, Group: f.Group, Variable: f.MuVar, Share: f.Share, Memberships: copyMap(m.mu[f.MuVar])}
		if cv, ok := m.custom[f.MuVar]; ok {
			fi.Label, fi.Unit = cv.Label, cv.Unit
		}
		out[i] = fi
	}
	return out
}

// Report: F1/F2′ diagnostics of a demand profile over this model's variables.
func (m *Model) Report(profile map[string]float64) (WeightReport, error) {
	return ComputeWeights(profile, m.mu, m.categories)
}

// Weights: per-dimension weight vector (FeatureNames order) for a demand profile.
// A nil profile means "no mission": every variable weighs the same.
func (m *Model) Weights(profile map[string]float64) (Vector, error) {
	if profile == nil {
		return m.expand(m.uniformPerVar(), m.FeatureNames())
	}
	rep, err := m.Report(profile)
	if err != nil {
		return nil, err
	}
	return m.expand(reportPerVar(rep), m.FeatureNames())
}

// ValidateProfile checks a mission demand profile without computing anything.
func ValidateProfile(profile map[string]float64) error {
	ok := make(map[string]bool, len(Categories))
	for _, c := range Categories {
		ok[c] = true
	}
	if profile == nil {
		return errors.New("demand: missing")
	}
	return validateVector(profile, ok, "demand", false)
}package knn

import (
	"errors"
	"math"
	"sort"
)

type Vector []float64

type Candidate struct {
	ID     string
	Name   string
	Vector Vector
}

type Match struct {
	RegionID   string  `json:"regionId"`
	Name       string  `json:"name"`
	Distance   float64 `json:"distance"`
	Similarity float64 `json:"similarity"`
	Coverage   float64 `json:"coverage"` // fracción del peso total con datos en ambas regiones
}

const MinCoverage = 0.5

// WeightedDistance: weighted Euclidean distance with missing data.
//
// Let O be the set of dimensions observed in both regions, W = Σ_i w_i, and
// W_O = Σ_{i∈O} w_i. Then:
//
//	d = sqrt( W · Σ_{i∈O} w_i (a_i − b_i)² / W_O )      coverage = W_O / W
//
// Missing dimensions are omitted and the weight is renormalized over the
// present ones; this is the same treatment as Gower's distance (1971).
// Properties (tests in knn_test.go):
//   - Without missing values, it is exactly sqrt(Σ w_i Δ_i²).
//   - It is a metric if w_i > 0; with any w_i = 0 (a variable that the mission does
//     not request) it is a pseudometric. With missing values, the triangle inequality may
//     fail; which is why coverage is reported.
//   - Scale invariance: w → c·w ⇒ d → √c·d; order and similarity do not change.
//   - After min-max, |Δ_i| ≤ 1 ⇒ d ≤ sqrt(W) = d_max ⇒ sim = 1 − d/d_max ∈ [0, 1].
//   - Without any common dimension (W_O = 0): d = d_max, sim = 0, coverage = 0.
func WeightedDistance(a, b, w Vector) (dist, coverage float64, err error) {
	if len(a) != len(b) || len(a) != len(w) {
		return 0, 0, errors.New("Vectors with different len")
	}
	total, obs, sum := 0.0, 0.0, 0.0
	for i := range a {
		if w[i] < 0 || math.IsNaN(w[i]) {
			return 0, 0, errors.New("negative weights o NaN")
		}
		total += w[i]
		if math.IsNaN(a[i]) || math.IsNaN(b[i]) {
			continue
		}
		d := a[i] - b[i]
		obs += w[i]
		sum += w[i] * d * d
	}
	if !(total > 0) {
		return 0, 0, errors.New("Sum must be > 0")
	}
	if obs == 0 {
		return math.Sqrt(total), 0, nil
	}
	return math.Sqrt(total * sum / obs), obs / total, nil
}

func FindMostSimilar(target Candidate, pool []Candidate, w Vector, k int) ([]Match, error) {
	if k <= 0 {
		return nil, errors.New("k must be > 0")
	}
	total := 0.0
	for _, wi := range w {
		total += wi
	}
	maxDist := math.Sqrt(total)

	matches := make([]Match, 0, len(pool))
	for _, c := range pool {
		d, cov, err := WeightedDistance(target.Vector, c.Vector, w)
		if err != nil {
			return nil, err
		}
		sim := 0.0
		if maxDist > 0 {
			sim = 1 - d/maxDist
		}
		matches = append(matches, Match{RegionID: c.ID, Name: c.Name, Distance: d, Similarity: sim, Coverage: cov})
	}

	sort.SliceStable(matches, func(i, j int) bool {
		oi, oj := matches[i].Coverage >= MinCoverage, matches[j].Coverage >= MinCoverage
		if oi != oj {
			return oi
		}
		if matches[i].Distance != matches[j].Distance {
			return matches[i].Distance < matches[j].Distance
		}
		return matches[i].Coverage > matches[j].Coverage
	})

	if len(matches) > k {
		matches = matches[:k]
	}
	return matches, nil
}package knn

// Compatibility breakdown by feature.
//
// The overall index that ranks KNN is sim = 1 − d/d_max. With W_O being the weight of
// the dimensions observed in both regions and Δ_i the normalized difference:
//
//  d/d_max = sqrt( Σ_{i∈O} w_i Δ_i² / W_O )          sim = 1 − d/d_max
//
// This file DOES NOT recalculate anything with another formula: it starts from the same normalized vectors
// (target already projected to the terrestrial range) and the same weights
// that FindMostSimilar used, and distributes that same quantity among the dimensions.
//
// For each dimension i:
//
//  Compatibility = 1 − |Δ_i|             how similar the values are (0–1).
//                                        DOES NOT depend on the filter: Δ_i comes solely from the data.
//  Weight        = w_i / Σw              how much that dimension weighs in the filter.
//  LossShare     = w_i Δ_i² / Σ_O w Δ²   what fraction of the loss (1 − sim)
//                                        is due to this dimension; Σ = 1.
//
// Weight and LossShare do change with the filter: they explain why the
// same region yields a different overall index under another mission.

import (
	"errors"
	"fmt"
	"math"

	"spaceapps/jsonParser"
)

// FeatureCompat describes a dimension (JSON variable) in the comparison
// between the target (Moon/Mars) and a terrestrial candidate. Missing values
// come out as null in JSON (never NaN, which would break encoding/json).
type FeatureCompat struct {
	Name  string `json:"name"`
	Group string `json:"group"`

	TargetValue *float64 `json:"targetValue"`
	EarthValue  *float64 `json:"earthValue"`
	TargetNorm  *float64 `json:"targetNorm"`
	EarthNorm   *float64 `json:"earthNorm"`

	TargetClamped bool `json:"targetClamped"`

	Observed bool `json:"observed"`

	Compatibility *float64 `json:"compatibility"`
	Weight        float64  `json:"weight"`
	LossShare     *float64 `json:"lossShare"`
}

func finitePtr(x float64) *float64 {
	if math.IsNaN(x) || math.IsInf(x, 0) {
		return nil
	}
	return &x
}

// CompareFeatures breaks down the target-candidate comparison by dimension.
// target and cand are the normalized Candidates returned by Prepare (the same
// pair that FindMostSimilar received); stats, those from PrepareWithStats; w, the
// weights of the filter. It returns one entry per dimension, in the order of FeatureNames().

func CompareFeatures(targetRegion, candRegion jsonParser.Region, target, cand Candidate, stats Stats, w Vector) ([]FeatureCompat, error) {
	return Default.CompareFeatures(targetRegion, candRegion, target, cand, stats, w)
}

func (m *Model) CompareFeatures(targetRegion, candRegion jsonParser.Region, target, cand Candidate, stats Stats, w Vector) ([]FeatureCompat, error) {
	n := len(m.features)
	if len(target.Vector) != n || len(cand.Vector) != n || len(w) != n || len(stats.Min) != n || len(stats.Max) != n {
		return nil, errors.New("Vectors, weights or statistics of different length to the number of dimenstions")
	}
	tRaw, err := m.ToVector(targetRegion)
	if err != nil {
		return nil, fmt.Errorf("region %s: %w", targetRegion.RegionId, err)
	}
	cRaw, err := m.ToVector(candRegion)
	if err != nil {
		return nil, fmt.Errorf("region %s: %w", candRegion.RegionId, err)
	}

	total := 0.0
	for _, wi := range w {
		if wi < 0 || math.IsNaN(wi) {
			return nil, errors.New("Negative weights NaN")
		}
		total += wi
	}
	if !(total > 0) {
		return nil, errors.New("Sum weights must be > 0")
	}

	q := make([]float64, n)
	observed := make([]bool, n)
	sumQ := 0.0
	for i := 0; i < n; i++ {
		a, b := target.Vector[i], cand.Vector[i]
		if math.IsNaN(a) || math.IsNaN(b) {
			continue
		}
		observed[i] = true
		d := a - b
		q[i] = w[i] * d * d
		sumQ += q[i]
	}

	out := make([]FeatureCompat, n)
	for i, f := range m.features {
		fc := FeatureCompat{
			Name:        f.Name,
			Group:       f.Group,
			TargetValue: finitePtr(tRaw[i]),
			EarthValue:  finitePtr(cRaw[i]),
			TargetNorm:  finitePtr(target.Vector[i]),
			EarthNorm:   finitePtr(cand.Vector[i]),
			Observed:    observed[i],
			Weight:      w[i] / total,
		}
		lo, hi := stats.Min[i], stats.Max[i]
		if x := tRaw[i]; !math.IsNaN(x) && !math.IsInf(lo, 0) && !math.IsInf(hi, 0) {
			fc.TargetClamped = x < lo || x > hi
		}
		if observed[i] {
			delta := math.Abs(target.Vector[i] - cand.Vector[i])
			c := math.Min(1, math.Max(0, 1-delta))
			fc.Compatibility = &c
			share := 0.0
			if sumQ > 0 {
				share = q[i] / sumQ
			}
			fc.LossShare = &share
		}
		out[i] = fc
	}
	return out, nil
}
