				if sim := 1 - math.Sqrt(q/wObs); math.Abs(sim-m.Similarity) > 1e-9 {
					t.Errorf("%q/%s: índice recompuesto %v ≠ similarity %v", f, m.RegionID, sim, m.Similarity)
				}
			}
			if math.Abs(wObs-m.Coverage) > 1e-9 {
				t.Errorf("%q/%s: cobertura %v ≠ %v", f, m.RegionID, wObs, m.Coverage)
			}
			if q > 0 && math.Abs(shares-1) > 1e-9 {
				t.Errorf("%q/%s: Σ lossShare = %v, esperaba 1", f, m.RegionID, shares)
			}
		}
	}
}

// Misma región, mismo candidato, distinto filtro: la compatibilidad de cada
// dimensión es la misma (sale de los datos) pero el peso, la pérdida atribuida
// y el índice general cambian.
func TestBreakdownChangesWithFilter(t *testing.T) {
	sel, earth := loadBreakdownData(t)
	target, pool, stats, err := PrepareWithStats(sel, earth)
	if err != nil {
		t.Fatal(err)
	}
	cand := pool[0]
	reg := byID(earth)[cand.ID]
	ws := allWeights(t)
	rover, err := CompareFeatures(sel, reg, target, cand, stats, ws["rover"])
	if err != nil {
		t.Fatal(err)
	}
	edl, err := CompareFeatures(sel, reg, target, cand, stats, ws["edl"])
	if err != nil {
		t.Fatal(err)
	}
	wDiff, lDiff := false, false
	for i := range rover {
		if rover[i].Observed != edl[i].Observed {
			t.Fatal("la observabilidad no depende del filtro")
		}
		if rover[i].Observed && math.Abs(*rover[i].Compatibility-*edl[i].Compatibility) > tol {
			t.Errorf("%s: la compatibilidad por dimensión no debe depender del filtro", rover[i].Name)
		}
		if math.Abs(rover[i].Weight-edl[i].Weight) > 1e-6 {
			wDiff = true
		}
		if rover[i].Observed && math.Abs(*rover[i].LossShare-*edl[i].LossShare) > 1e-6 {
			lDiff = true
		}
	}
	if !wDiff || !lDiff {
		t.Errorf("rover y edl deben dar pesos (%v) y aportes a la pérdida (%v) distintos", wDiff, lDiff)
	}
	mr, _ := FindMostSimilar(target, []Candidate{cand}, ws["rover"], 1)
	me, _ := FindMostSimilar(target, []Candidate{cand}, ws["edl"], 1)
	if math.Abs(mr[0].Similarity-me[0].Similarity) < 1e-9 {
		t.Error("el índice general de este par debería diferir entre rover y edl")
	}
}

// Datos ausentes: observed=false, valores null, nada de NaN en el JSON.
func TestBreakdownMissingIsNullInJSON(t *testing.T) {
	sel, earth := loadBreakdownData(t)
	target, pool, stats, _ := PrepareWithStats(sel, earth)
	w, _ := WeightsFor("rover", FeatureNames())
	fs, err := CompareFeatures(sel, byID(earth)[pool[0].ID], target, pool[0], stats, w)
	if err != nil {
		t.Fatal(err)
	}
	raw, err := json.Marshal(fs) // fallaría si algún valor fuera NaN/Inf
	if err != nil {
		t.Fatalf("no serializable: %v", err)
	}
	var back []map[string]any
	if err := json.Unmarshal(raw, &back); err != nil {
		t.Fatal(err)
	}
	core, audit := 0, 0
	for _, x := range fs {
		switch x.Group {
		case "core":
			core++
		case "audit":
			audit++
		}
		if x.Name == "ground_ice_index" { // null en todo moon.json
			if x.Observed || x.Compatibility != nil || x.LossShare != nil || x.TargetValue != nil || x.EarthValue != nil {
				t.Errorf("ground_ice_index null debe salir como no observado: %+v", x)
			}
		}
	}
	if core != 10 || audit != 16 {
		t.Errorf("esperaba 10 core + 16 audit, hay %d + %d", core, audit)
	}
}

// Un objetivo fuera del rango terrestre se marca y conserva su valor crudo.
func TestBreakdownFlagsClamped(t *testing.T) {
	sel, earth := loadBreakdownData(t)
	far := sel
	ins := 5 * *sel.CoreVariables.Insolation
	far.CoreVariables.Insolation = &ins
	target, pool, stats, _ := PrepareWithStats(far, earth)
	w, _ := WeightsFor("", FeatureNames())
	fs, err := CompareFeatures(far, byID(earth)[pool[0].ID], target, pool[0], stats, w)
	if err != nil {
		t.Fatal(err)
	}
	for _, x := range fs {
		if x.Name != "insolation" {
			continue
		}
		if !x.TargetClamped || *x.TargetValue != ins || *x.TargetNorm != 1 {
			t.Errorf("insolation fuera de rango: %+v", x)
		}
	}
}

func TestBreakdownRejectsBadInput(t *testing.T) {
	sel, earth := loadBreakdownData(t)
	target, pool, stats, _ := PrepareWithStats(sel, earth)
	reg := byID(earth)[pool[0].ID]
	if _, err := CompareFeatures(sel, reg, target, pool[0], stats, Vector{1}); err == nil {
		t.Error("pesos de longitud incorrecta deben ser error")
	}
	if _, err := CompareFeatures(sel, reg, target, pool[0], stats, make(Vector, len(features))); err == nil {
		t.Error("pesos que suman 0 deben ser error")
	}
}
package knn

import (
	"encoding/json"
	"errors"
	"math"
	"math/rand/v2"
	"os"
	"testing"

	"spaceapps/jsonParser"
)

const tol = 1e-9

func randVec(r *rand.Rand, n int, missing float64) Vector {
	v := make(Vector, n)
	for i := range v {
		if r.Float64() < missing {
			v[i] = math.NaN()
		} else {
			v[i] = r.Float64()
		}
	}
	return v
}

func allWeights(t *testing.T) map[string]Vector {
	t.Helper()
	out := map[string]Vector{}
	for _, f := range append([]string{""}, MissionNames()...) {
		w, err := WeightsFor(f, FeatureNames())
		if err != nil {
			t.Fatal(err)
		}
		out[f] = w
	}
	return out
}

func TestWeightsForErrors(t *testing.T) {
	if _, err := WeightsFor("nope", FeatureNames()); !errors.Is(err, ErrUnknownFilter) {
		t.Errorf("filtro desconocido: %v", err)
	}
	if _, err := WeightsFor("rover", append(FeatureNames(), "variable_nueva")); err == nil {
		t.Error("una dimensión sin modelo debe ser error, no peso 0 silencioso")
	}
}

// Sin ausentes: métrica (filtro vacío, todos los w > 0) o pseudométrica
// (misiones con w = 0 en variables que no piden). Ambas cumplen la desigualdad
// triangular.
func TestDistanceAxiomsCompleteData(t *testing.T) {
	r := rand.New(rand.NewPCG(1, 2))
	n := len(features)
	for f, w := range allWeights(t) {
		for trial := 0; trial < 2000; trial++ {
			a, b, c := randVec(r, n, 0), randVec(r, n, 0), randVec(r, n, 0)
			dab, cov, _ := WeightedDistance(a, b, w)
			dba, _, _ := WeightedDistance(b, a, w)
			dac, _, _ := WeightedDistance(a, c, w)
			dbc, _, _ := WeightedDistance(b, c, w)
			daa, _, _ := WeightedDistance(a, a, w)
			if dab < 0 || daa != 0 || math.Abs(dab-dba) > tol || dac > dab+dbc+tol || cov != 1 {
				t.Fatalf("filtro %q viola axiomas", f)
			}
			// Sin ausentes coincide con la fórmula clásica sqrt(Σ wΔ²).
			s := 0.0
			for i := range a {
				s += w[i] * (a[i] - b[i]) * (a[i] - b[i])
			}
			if math.Abs(dab-math.Sqrt(s)) > tol {
				t.Fatalf("filtro %q: no reduce a la euclídea ponderada", f)
			}
		}
	}
	// Filtro vacío: todos los pesos > 0 → métrica estricta.
	for _, x := range allWeights(t)[""] {
		if !(x > 0) {
			t.Fatal("sin filtro todos los pesos deben ser > 0")
		}
	}
}

func TestScaleInvarianceWithMissing(t *testing.T) {
	r := rand.New(rand.NewPCG(3, 4))
	n := len(features)
	pool := make([]Candidate, 60)
	for i := range pool {
		pool[i] = Candidate{ID: string(rune('A'+i%26)) + string(rune('a'+i/26)), Vector: randVec(r, n, 0.2)}
	}
	target := Candidate{Vector: randVec(r, n, 0.2)}
	for f, w := range allWeights(t) {
		scaled := make(Vector, n)
		for i := range w {
			scaled[i] = 37.5 * w[i]
		}
		m1, _ := FindMostSimilar(target, pool, w, 10)
		m2, _ := FindMostSimilar(target, pool, scaled, 10)
		for i := range m1 {
			if m1[i].RegionID != m2[i].RegionID || math.Abs(m1[i].Similarity-m2[i].Similarity) > tol ||
				math.Abs(m1[i].Coverage-m2[i].Coverage) > tol {
				t.Fatalf("filtro %q: escalar los pesos cambió el resultado en la posición %d", f, i)
			}
		}
	}
}

func TestBoundsWithMissing(t *testing.T) {
	r := rand.New(rand.NewPCG(5, 6))
	n := len(features)
	pool := make([]Candidate, 300)
	for i := range pool {
		pool[i] = Candidate{ID: "x", Vector: randVec(r, n, r.Float64())}
	}
	corner, opposite, empty := make(Vector, n), make(Vector, n), make(Vector, n)
	for i := range opposite {
		opposite[i], empty[i] = 1, math.NaN()
	}
	pool = append(pool, Candidate{ID: "opuesto", Vector: opposite}, Candidate{ID: "vacio", Vector: empty})
	for f, w := range allWeights(t) {
		ms, _ := FindMostSimilar(Candidate{Vector: corner}, pool, w, len(pool))
		for _, m := range ms {
			if m.Similarity < -tol || m.Similarity > 1+tol || m.Distance > 1+tol || m.Coverage < 0 || m.Coverage > 1+tol {
				t.Fatalf("filtro %q: sim=%v d=%v cov=%v fuera de rango", f, m.Similarity, m.Distance, m.Coverage)
			}
		}
		for _, m := range ms {
			if m.RegionID == "opuesto" && math.Abs(m.Similarity) > tol {
				t.Errorf("filtro %q: la esquina opuesta debe tener sim = 0", f)
			}
			if m.RegionID == "vacio" && (m.Coverage != 0 || m.Similarity != 0) {
				t.Errorf("filtro %q: sin datos comunes debe dar cobertura 0 y sim 0", f)
			}
		}
		if ms[len(ms)-1].Coverage >= MinCoverage {
			continue
		}
		// Ningún candidato con cobertura < MinCoverage va antes de uno que la cumple.
		seenLow := false
		for _, m := range ms {
			if m.Coverage < MinCoverage {
				seenLow = true
			} else if seenLow {
				t.Fatalf("filtro %q: cobertura baja ordenada antes que una suficiente", f)
			}
		}
	}
}

// ---------------------------------------------------------------- datos reales

func loadMars(t *testing.T) []jsonParser.Region {
	t.Helper()
	raw, err := os.ReadFile("testdata/mars.json")
	if err != nil {
		t.Fatal(err)
	}
	var data jsonParser.PlanetInformation
	if err := json.Unmarshal(raw, &data); err != nil {
		t.Fatal(err)
	}
	return data.Regions
}

// null en el JSON → dato ausente (NaN), NO 0.
func TestNullIsMissingNotZero(t *testing.T) {
	mars := loadMars(t)
	idx := map[string]int{}
	for i, n := range FeatureNames() {
		idx[n] = i
	}
	for _, r := range mars {
		v, err := ToVector(r)
		if err != nil {
			t.Fatal(err)
		}
		if len(v) != 26 {
			t.Fatalf("vector de %d dimensiones, esperaba 26", len(v))
		}
		if !math.IsNaN(v[idx["salinity_wt_pct"]]) {
			t.Errorf("%s: salinity null debía ser ausente", r.RegionId)
		}
		if v[idx["vegetation_ndvi"]] != 0 {
			t.Errorf("%s: ndvi 0.0 es un dato real, no ausente", r.RegionId)
		}
	}
	arcadia, _ := ToVector(mars[2])
	if !math.IsNaN(arcadia[idx["depth_to_bedrock_min_m"]]) || !math.IsNaN(arcadia[idx["depth_to_bedrock_max_m"]]) {
		t.Error("Arcadia: depth_to_bedrock null debía ser ausente")
	}
}

func TestPrepareNormalizesWithMissing(t *testing.T) {
	mars := loadMars(t)
	target, pool, err := Prepare(mars[0], mars[1:])
	if err != nil {
		t.Fatal(err)
	}
	for _, c := range append(pool, target) {
		for i, x := range c.Vector {
			if !math.IsNaN(x) && (x < 0 || x > 1) {
				t.Fatalf("%s[%s] = %v fuera de [0,1]", c.ID, features[i].Name, x)
			}
		}
	}
	w, _ := WeightsFor("rover", FeatureNames())
	ms, err := FindMostSimilar(target, pool, w, 2)
	if err != nil {
		t.Fatal(err)
	}
	for _, m := range ms {
		if !(m.Coverage > 0 && m.Coverage < 1) {
			t.Errorf("%s: con salinity ausente la cobertura debe estar en (0,1), es %v", m.RegionID, m.Coverage)
		}
	}
}

// ---------------------------------------------------------------- robustez

func TestRobustness(t *testing.T) {
	r := rand.New(rand.NewPCG(7, 8))
	n := len(features)
	pool := make([]Candidate, 30)
	for i := range pool {
		pool[i] = Candidate{ID: string(rune('a' + i)), Vector: randVec(r, n, 0.1)}
	}
	tgt := Candidate{Vector: randVec(r, n, 0.1)}
	for _, f := range append([]string{""}, MissionNames()...) {
		rob, err := AnalyzeRobustness(tgt, pool, f, 3, 0, 50, 42)
		if err != nil {
			t.Fatal(err)
		}
		if rob.Top1Stability != 1 || math.Abs(rob.MeanTopKJaccard-1) > tol {
			t.Errorf("%q: con ε=0 todo debe ser estable: %+v", f, rob)
		}
		a, _ := AnalyzeRobustness(tgt, pool, f, 3, 0.2, 100, 42)
		b, _ := AnalyzeRobustness(tgt, pool, f, 3, 0.2, 100, 42)
		if a.Top1Stability != b.Top1Stability || a.MeanTopKJaccard != b.MeanTopKJaccard {
			t.Errorf("%q: no determinista con seed fijo", f)
		}
	}
}

