// Paridad con pesos_mision.py: la afinidad F1 y N* deben coincidir con lo que
// calcula el Python, y F2′ con su fórmula evaluada en Python. Si alguien
// cambia Mu o Missions en un lado y no en el otro, este test falla.
func TestParityWithPython(t *testing.T) {
	raw, err := os.ReadFile("testdata/golden_python.json")
	if err != nil {
		t.Fatal(err)
	}
	var golden map[string]struct {
		NStar         float64            `json:"nStar"`
		Affinity      map[string]float64 `json:"affinity"`
		WeightF2Prime map[string]float64 `json:"weightF2prime"`
	}
	if err := json.Unmarshal(raw, &golden); err != nil {
		t.Fatal(err)
	}
	if len(golden) != len(Missions) {
		t.Fatalf("el Python tiene %d misiones y el Go %d", len(golden), len(Missions))
	}
	for m, g := range golden {
		rep, ok := missionReports[m]
		if !ok {
			t.Fatalf("misión %s no existe en Go", m)
		}
		if math.Abs(rep.NStar-g.NStar) > 1e-9 {
			t.Errorf("%s: N* Go=%v Python=%v", m, rep.NStar, g.NStar)
		}
		for v, a := range g.Affinity {
			if math.Abs(rep.Variables[v].Affinity-a) > 1e-12 {
				t.Errorf("%s/%s: afinidad Go=%v Python=%v", m, v, rep.Variables[v].Affinity, a)
			}
			if math.Abs(rep.Variables[v].Weight-g.WeightF2Prime[v]) > 1e-12 {
				t.Errorf("%s/%s: peso Go=%v Python=%v", m, v, rep.Variables[v].Weight, g.WeightF2Prime[v])
			}
		}
	}
}

// (Δmin² + Δmax²)/2 = Δcentro² + Δsemiancho²: justifica Share = 0.5 para depth_to_bedrock.
func TestIntervalSplitIdentity(t *testing.T) {
	r := rand.New(rand.NewPCG(3, 3))
	for i := 0; i < 1000; i++ {
		a1, a2, b1, b2 := r.Float64(), r.Float64(), r.Float64(), r.Float64()
		lhs := ((a1-b1)*(a1-b1) + (a2-b2)*(a2-b2)) / 2
		dm := (a1+a2)/2 - (b1+b2)/2
		dh := (a2-a1)/2 - (b2-b1)/2
		if math.Abs(lhs-(dm*dm+dh*dh)) > 1e-12 {
			t.Fatal("identidad del intervalo falla")
		}
	}
}

