package knn

// Port de tests_pesos.py, adaptado a F2′, más paridad numérica con el Python.

import (
	"encoding/json"
	"fmt"
	"math"
	"math/rand/v2"
	"os"
	"testing"
)

// ---------------------------------------------------------------- utilidades

// gamma(α, 1) por Marsaglia–Tsang (con el truco de α < 1).
func gammaVar(r *rand.Rand, a float64) float64 {
	if a < 1 {
		return gammaVar(r, a+1) * math.Pow(r.Float64(), 1/a)
	}
	d := a - 1.0/3
	c := 1 / math.Sqrt(9*d)
	for {
		x := r.NormFloat64()
		v := 1 + c*x
		if v <= 0 {
			continue
		}
		v = v * v * v
		u := r.Float64()
		if math.Log(u) < 0.5*x*x+d-d*v+d*math.Log(v) {
			return d * v
		}
	}
}

func dirichlet(r *rand.Rand, k int, a float64) []float64 {
	g := make([]float64, k)
	s := 0.0
	for i := range g {
		g[i] = gammaVar(r, a)
		s += g[i]
	}
	if s == 0 { // α muy pequeño puede dar todo 0 por underflow
		g[r.IntN(k)] = 1
		return g
	}
	for i := range g {
		g[i] /= s
	}
	return g
}

// caso aleatorio idéntico en espíritu a caso_aleatorio() de tests_pesos.py
func randomCase(r *rand.Rand) (map[string]map[string]float64, map[string]float64, []string) {
	C := 1 + r.IntN(12)
	n := 1 + r.IntN(60)
	cats := make([]string, C)
	for i := range cats {
		cats[i] = fmt.Sprintf("c%d", i)
	}
	mu := map[string]map[string]float64{}
	for j := 0; j < n; j++ {
		row := map[string]float64{}
		switch r.IntN(3) {
		case 0: // puro
			row[cats[r.IntN(C)]] = 1
		case 1: // dos
			a, b := cats[r.IntN(C)], cats[r.IntN(C)]
			t := r.Float64()
			row[a] += t
			row[b] += 1 - t
		default: // mezcla
			p := dirichlet(r, C, []float64{0.2, 1, 5}[r.IntN(3)])
			for i, c := range cats {
				if p[i] > 0 {
					row[c] = p[i]
				}
			}
			s := 0.0
			for _, x := range row {
				s += x
			}
			for c := range row {
				row[c] /= s
			}
		}
		mu[fmt.Sprintf("v%d", j)] = row
	}
	k := 1 + r.IntN(C)
	perm := r.Perm(C)[:k]
	p := dirichlet(r, k, []float64{0.1, 1, 10}[r.IntN(3)])
	profile := map[string]float64{}
	for i, idx := range perm {
		profile[cats[idx]] = p[i]
	}
	if s := sumMap(profile); !(s > 0) {
		profile[cats[perm[0]]] = 1
	}
	return mu, profile, cats
}

func sumMap(m map[string]float64) float64 {
	s := 0.0
	for _, x := range m {
		s += x
	}
	return s
}

func copyMu(mu map[string]map[string]float64) map[string]map[string]float64 {
	out := map[string]map[string]float64{}
	for v, row := range mu {
		out[v] = map[string]float64{}
		for c, x := range row {
			out[v][c] = x
		}
	}
	return out
}

// pieces devuelve q_jc = μ_jc d̃_c / n_c (las porciones de la derivación).
func pieces(rep WeightReport, mu map[string]map[string]float64) map[string]map[string]float64 {
	nc := map[string]float64{}
	for _, row := range mu {
		for c, x := range row {
			nc[c] += x
		}
	}
	q := map[string]map[string]float64{}
	for v, row := range mu {
		q[v] = map[string]float64{}
		for c, x := range row {
			if nc[c] > 0 {
				q[v][c] = x * rep.Profile[c] / nc[c]
			}
		}
	}
	return q
}

func properties(t *testing.T, label string, mu map[string]map[string]float64, profile map[string]float64, cats []string) WeightReport {
	t.Helper()
	rep, err := ComputeWeights(profile, mu, cats)
	if err != nil {
		t.Fatalf("%s: %v", label, err)
	}
	n := float64(len(mu))
	sw, sf := 0.0, 0.0
	for v, x := range rep.Variables {
		// P1 pesos válidos y factor con media 1
		if math.IsNaN(x.Weight) || math.IsInf(x.Weight, 0) || x.Weight < 0 {
			t.Fatalf("%s: peso inválido en %s: %v", label, v, x.Weight)
		}
		// P3 afinidad en [0, 1]
		if x.Affinity < -1e-12 || x.Affinity > 1+1e-12 {
			t.Fatalf("%s: afinidad fuera de [0,1]", label)
		}
		sw += x.Weight
		sf += x.Factor
	}
	if math.Abs(sw-1) > 1e-12 || math.Abs(sf/n-1) > 1e-12 {
		t.Fatalf("%s: Σw = %v, media factor = %v", label, sw, sf/n)
	}
	// P6 ángulo de Hellinger en [0, acos(1/√n)]
	if rep.AngleDeg < -1e-9 || rep.AngleDeg > math.Acos(1/math.Sqrt(n))*180/math.Pi+1e-6 {
		t.Fatalf("%s: ángulo fuera de rango: %v", label, rep.AngleDeg)
	}
	if rep.NoAffinity {
		return rep
	}
	// P-cat (la decisión): cada categoría recibe exactamente su demanda.
	q := pieces(rep, mu)
	got := map[string]float64{}
	for _, row := range q {
		for c, x := range row {
			got[c] += x
		}
	}
	for c, dc := range rep.Profile {
		if math.Abs(got[c]-dc) > 1e-12 {
			t.Fatalf("%s: categoría %s recibe %v, demanda %v", label, c, got[c], dc)
		}
	}
	// y w_j = Σ_c q_jc
	for v, row := range q {
		if math.Abs(sumMap(row)-rep.Variables[v].Weight) > 1e-12 {
			t.Fatalf("%s: w_%s != Σ_c q", label, v)
		}
	}
	return rep
}

// ---------------------------------------------------------------- fuzz (4000)

func TestFuzzProperties(t *testing.T) {
	r := rand.New(rand.NewPCG(7, 7))
	for i := 0; i < 4000; i++ {
		mu, profile, cats := randomCase(r)
		label := fmt.Sprintf("fuzz#%d", i)
		rep := properties(t, label, mu, profile, cats)

		// P8 invariancia a escala del perfil
		c := []float64{0.01, 3, 1000}[r.IntN(3)]
		scaled := map[string]float64{}
		for k, x := range profile {
			scaled[k] = c * x
		}
		rep2, _ := ComputeWeights(scaled, mu, cats)
		// P9 invariancia a agregar una categoría vacía
		rep3, _ := ComputeWeights(profile, mu, append(append([]string{}, cats...), "VACIA"))
		for v := range mu {
			if math.Abs(rep.Variables[v].Weight-rep2.Variables[v].Weight) > 1e-12 {
				t.Fatalf("%s: no invariante a escala de d", label)
			}
			if math.Abs(rep.Variables[v].Weight-rep3.Variables[v].Weight) > 1e-12 {
				t.Fatalf("%s: cambia al agregar categoría vacía", label)
			}
		}
		if rep.NoAffinity {
			continue
		}

		// Optimalidad (derivación por KL): mover masa entre dos porciones de la
		// MISMA categoría mantiene las restricciones y debe empeorar la KL.
		q := pieces(rep, mu)
		kl := func(q map[string]map[string]float64) float64 {
			s := 0.0
			for v, row := range q {
				for c, x := range row {
					if x > 0 {
						s += x * math.Log(x/mu[v][c])
					}
				}
			}
			return s
		}
		base := kl(q)
		for c := range rep.Profile {
			var holders []string
			for _, v := range sortedKeys(q) {
				if q[v][c] > 1e-6 {
					holders = append(holders, v)
				}
			}
			if len(holders) < 2 {
				continue
			}
			a, b := holders[0], holders[1]
			eps := 1e-3 * math.Min(q[a][c], q[b][c])
			q[a][c] += eps
			q[b][c] -= eps
			if kl(q) <= base {
				t.Fatalf("%s: la solución no minimiza la KL (categoría %s)", label, c)
			}
			q[a][c] -= eps
			q[b][c] += eps
			break
		}

		// Invariancia por replicación: duplicar una variable cualquiera (pura o
		// mixta) deja la masa de CADA categoría en su demanda (properties lo
		// comprueba sobre mu2) y no cambia el peso de las variables que no
		// comparten categoría con la duplicada.
		v := sortedKeys(mu)[r.IntN(len(mu))]
		mu2 := copyMu(mu)
		mu2[v+"_copia"] = mu[v]
		repD := properties(t, label+" duplicada", mu2, profile, cats)
		for u, row := range mu {
			shares := false
			for c := range row {
				if mu[v][c] > 0 {
					shares = true
				}
			}
			if !shares && math.Abs(rep.Variables[u].Weight-repD.Variables[u].Weight) > 1e-12 {
				t.Fatalf("%s: duplicar %s cambió %s, que no comparte categoría", label, v, u)
			}
		}
	}
}

