package knn

import (
	"encoding/json"
	"math"
	"os"
	"testing"

	"spaceapps/jsonParser"
)

// Los tests del desglose solo necesitan un objetivo y un catálogo con datos
// reales y algún null; usan testdata/moon.json para ambos (un sitio como
// objetivo y los otros 14 como catálogo). El desglose es independiente de qué
// planeta sea cada lado.
func loadBreakdownData(t *testing.T) (jsonParser.Region, []jsonParser.Region) {
	t.Helper()
	raw, err := os.ReadFile("testdata/moon.json")
	if err != nil {
		t.Fatal(err)
	}
	var info jsonParser.PlanetInformation
	if err := json.Unmarshal(raw, &info); err != nil {
		t.Fatal(err)
	}
	return info.Regions[1], append(append([]jsonParser.Region{}, info.Regions[:1]...), info.Regions[2:]...)
}

func byID(rs []jsonParser.Region) map[string]jsonParser.Region {
	m := map[string]jsonParser.Region{}
	for _, r := range rs {
		m[r.RegionId] = r
	}
	return m
}

// El índice recompuesto desde el desglose es EXACTAMENTE el Similarity del KNN,
// y la cobertura coincide, para todos los filtros y todos los candidatos.
func TestBreakdownReconstructsKNNIndex(t *testing.T) {
	sel, earth := loadBreakdownData(t)
	target, pool, stats, err := PrepareWithStats(sel, earth)
	if err != nil {
		t.Fatal(err)
	}
	regions := byID(earth)
	poolByID := map[string]Candidate{}
	for _, c := range pool {
		poolByID[c.ID] = c
	}
	for f, w := range allWeights(t) {
		ms, err := FindMostSimilar(target, pool, w, len(pool))
		if err != nil {
			t.Fatal(err)
		}
		for _, m := range ms {
			fs, err := CompareFeatures(sel, regions[m.RegionID], target, poolByID[m.RegionID], stats, w)
			if err != nil {
				t.Fatal(err)
			}
			if len(fs) != len(features) {
				t.Fatalf("esperaba %d dimensiones, hay %d", len(features), len(fs))
			}
			wTot, wObs, q, shares := 0.0, 0.0, 0.0, 0.0
			for _, x := range fs {
				wTot += x.Weight
				if !x.Observed {
					continue
				}
				wObs += x.Weight
				d := 1 - *x.Compatibility
				q += x.Weight * d * d
				shares += *x.LossShare
			}
			if math.Abs(wTot-1) > tol {
				t.Fatalf("%q/%s: Σ pesos = %v", f, m.RegionID, wTot)
			}
			if wObs > 0 {
				if sim := 1 - math.Sqrt(q/wObs); math.Abs(sim-m.Similarity) > 1e-9 {
					t.Errorf("%q/%s: índice recompuesto %v ≠ similarity %v", f, m.RegionID, sim, m.Similarity)
				}
			}
			if math.Abs(wObs-m.Coverage) > 1e-9 {
				t.Errorf("%q/%s: cobertura %v ≠ %v", f, m.RegionID, wObs, m.Coverage)
			}
			if q > 0 && math.Abs(shares-1) > 1e-9 {
				t.Errorf("%q/%s: Σ lossShare = %v, esperaba 1", f, m.RegionID, shares)
			}
		}
	}
}

