package API

import (
	"bytes"
	"encoding/json"
	"math"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"sync"
	"testing"

	"spaceapps/custom"
	"spaceapps/jsonParser"
)

func newServer(t *testing.T, own bool) http.Handler {
	t.Helper()
	p, err := jsonParser.New("../knn/testdata")
	if err != nil {
		t.Fatal(err)
	}
	s := &Server{Parser: p}
	if own {
		s.Custom = custom.NewStore()
	}
	return s.Routes()
}

func do(t *testing.T, h http.Handler, method, url string, body []byte) (*httptest.ResponseRecorder, map[string]any) {
	t.Helper()
	req := httptest.NewRequest(method, url, bytes.NewReader(body))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	var out map[string]any
	if rec.Body.Len() > 0 {
		if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
			t.Fatalf("%s %s: invalid JSON response: %v\n%s", method, url, err, rec.Body.String())
		}
	}
	return rec, out
}

func readFile(t *testing.T, path string) []byte {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func matchIDs(resp map[string]any) []string {
	var ids []string
	for _, m := range resp["matches"].([]any) {
		ids = append(ids, m.(map[string]any)["regionId"].(string))
	}
	return ids
}

// Built-in behaviour is unchanged (same as knn/testdata/snapshot_real.json).
# API del backend

```bash
cd backend
go run .                  # solo datos integrados
go run . --own-regions    # además acepta regiones, variables y misiones del usuario
go test -race ./...
```

Variables de entorno: `DATA_DIR` (por defecto `data`), `ADDR` y `ALLOWED_ORIGIN` (vacío = cualquier origen de `localhost`/`127.0.0.1`).
Con `--own-regions`, `ADDR` por defecto es `127.0.0.1:8080`, para que solo esta máquina pueda subir datos. Si se enlaza a otra dirección, el servidor lo avisa en el log.

## Endpoints

| Método | Ruta | Qué hace |
|---|---|---|
| GET | `/api/status` | Estado |
| GET | `/api/catalog` | Categorías, variables (con su tipo `memberships`), misiones (con su reporte de pesos), regiones por planeta y `capabilities.ownRegions` |
| GET | `/api/regions?planet=mars` | Regiones integradas + propias, `{ planet, regions: [...] }`. Cada región trae `source: "builtin" \| "custom"` |
| GET | `/api/analog?planet=&regionId=&filter=` | Top-3 análogos terrestres (lo usa el front) |
| POST | `/api/calculate` | Lo mismo con cuerpo `{"misiones":{"filter":"rover"},"caracteristicas":{"planet":"mars","regionId":"MARS-001"}}` |
| POST | `/api/custom/regions` | Sube el archivo de regiones (**reemplaza** el anterior) |
| POST | `/api/custom/missions` | Sube el archivo de misiones (**reemplaza** el anterior) |
| GET | `/api/custom` | Lo que está cargado |
| DELETE | `/api/custom` | Borra todo lo propio |

Sin `--own-regions`, los cuatro `/api/custom*` responden **403** con un mensaje que explica cómo activarlos.

`filter` puede ser vacío (todas las variables pesan igual), una misión integrada (`rover`, `edl`, `habitat`, `agua_bio`) o el `id` de una misión subida.

La respuesta de `/api/analog` incluye:
- `mission`: `null` si no hay filtro.
- `selectedRegion`.
- `matches[]`: cada uno con `region` completa, `similarity`, `coverage` y `features[]` (desglose por variable: valor, compatibilidad, peso y parte de la pérdida).
- `extrapolation`: variables del objetivo fuera del rango terrestre.

Los datos ausentes salen como `null`, ya no como 0.

## Archivo 1: regiones

Ejemplo completo: [`examples/custom_regions.example.json`](../examples/custom_regions.example.json).

```json
{
  "planet": "mars",
  "variables": [
    { "name": "magnetic_susceptibility", "label": "Susceptibilidad magnética", "unit": "1e-3 SI",
      "memberships": { "VOL": 0.7, "MEC": 0.3 } }
  ],
  "regions": [
    { "regionId": "UNI-MARS-01", "name": "...", "coordinates": { "latitude": 15, "longitude": -160 },
      "coreVariables": { "slope": 2.0 }, "auditVariables": { "salinity_wt_pct": null },
      "customVariables": { "magnetic_susceptibility": 4.2 } },
    { "planet": "earth", "regionId": "UNI-EARTH-01", "name": "...", "coordinates": { "latitude": 31.9, "longitude": -113.9 },
      "coreVariables": { "slope": 3.0 }, "customVariables": { "magnetic_susceptibility": 3.1 } }
  ]
}
```

- **Planeta:** `planet` vale `moon`, `mars` o `earth`. El de nivel superior es el valor por defecto, y cada región puede tener el suyo. Las regiones de Marte y la Luna son objetivos nuevos; las de la Tierra se suman al catálogo de análogos.

