package main

// Generates a 96x96 status badge: green disc with a white check mark.
import (
	"image"
	"image/color"
	"image/png"
	"math"
	"os"
)

func segDist(px, py, ax, ay, bx, by float64) float64 {
	dx, dy := bx-ax, by-ay
	t := math.Max(0, math.Min(1, ((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy)))
	return math.Hypot(px-(ax+t*dx), py-(ay+t*dy))
}

func main() {
	const n = 96
	img := image.NewNRGBA(image.Rect(0, 0, n, n))
	green := color.NRGBA{0x1f, 0x9d, 0x55, 0xff}
	for y := 0; y < n; y++ {
		for x := 0; x < n; x++ {
