package main

// HTTP contract tests of the real server (cors + API.Server) with the real
// data (knn/testdata).

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"spaceapps/API"
	"spaceapps/jsonParser"
)

func newTestServer(t *testing.T, origin string, ownRegions bool) *httptest.Server {
	t.Helper()
	p, err := jsonParser.New("knn/testdata")
	if err != nil {
		t.Fatal(err)
	}
	srv := httptest.NewServer(cors(origin, newServer(p, ownRegions).Routes()))
	t.Cleanup(srv.Close)
	return srv
}

func decode(t *testing.T, resp *http.Response) map[string]any {
	t.Helper()
	defer resp.Body.Close()
	if ct := resp.Header.Get("Content-Type"); !strings.HasPrefix(ct, "application/json") {
		t.Fatalf("Content-Type %q, want application/json", ct)
	}
	var body map[string]any
	if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
		t.Fatal(err)
	}
	return body
}

func TestAnalogStatusCodes(t *testing.T) {
	srv := newTestServer(t, "", false)
	cases := []struct {
		query string
		want  int
	}{
		{"planet=mars&regionId=MARS-001&filter=rover", http.StatusOK},
		{"planet=MOON&regionId=MOON-003&filter=", http.StatusOK}, // planet is normalized to lowercase
		{"planet=mars&regionId=MARS-001", http.StatusOK},         // no filter
		{"planet=venus&regionId=MARS-001", http.StatusBadRequest},
		{"planet=../etc&regionId=MARS-001", http.StatusBadRequest},
		{"planet=mars&regionId=../../earth", http.StatusBadRequest},
		{"planet=mars&regionId=", http.StatusBadRequest},
		{"planet=mars&regionId=MARS-999", http.StatusNotFound},
		{"planet=mars&regionId=MOON-001", http.StatusNotFound}, // region from another planet
		{"planet=mars&regionId=MARS-001&filter=thermal_cycles", http.StatusBadRequest},
	}
	for _, c := range cases {
		resp, err := http.Get(srv.URL + "/api/analog?" + c.query)
		if err != nil {
			t.Fatal(err)
		}
		body := decode(t, resp)
		if resp.StatusCode != c.want {
			t.Errorf("%s: status %d, want %d", c.query, resp.StatusCode, c.want)
		}
		if c.want != http.StatusOK && body["error"] == nil {
			t.Errorf("%s: error response without an \"error\" field", c.query)
		}
	}
}

func TestAnalogResponseShape(t *testing.T) {
	srv := newTestServer(t, "", false)
	resp, err := http.Get(srv.URL + "/api/analog?planet=mars&regionId=MARS-001&filter=rover")
	if err != nil {
		t.Fatal(err)
	}
	body := decode(t, resp)
	matches, _ := body["matches"].([]any)
	if len(matches) != API.TopK {
		t.Fatalf("expected %d matches, got %d", API.TopK, len(matches))
	}
	for _, m := range matches {
		mm := m.(map[string]any)
		for _, k := range []string{"regionId", "similarity", "coverage", "region", "features"} {
			if _, ok := mm[k]; !ok {
				t.Errorf("match missing %q", k)
			}
		}
	}
	for _, k := range []string{"robustness", "extrapolation", "selectedRegion", "mission"} {
		if _, ok := body[k]; !ok {
			t.Errorf("response missing %q", k)
		}
	}
	rob := body["robustness"].(map[string]any)
	if rob["trials"].(float64) != API.RobustTrials || rob["perturbs"] != "mission_profile" {
		t.Errorf("unexpected robustness block: %v", rob)
	}
	if s := rob["top1Stability"].(float64); s < 0 || s > 1 {
		t.Errorf("top1Stability %v outside [0,1]", s)
	}
	// null stays null (not 0) in the selected region
	audit := body["selectedRegion"].(map[string]any)["auditVariables"].(map[string]any)
	if v, ok := audit["salinity_wt_pct"]; !ok || v != nil {
		t.Errorf("salinity_wt_pct must be null, got %v", v)
	}
}

// POST /api/calculate returns the same result as GET /api/analog, robustness included.
func TestCalculateMatchesAnalog(t *testing.T) {
	srv := newTestServer(t, "", false)
	resp, err := http.Get(srv.URL + "/api/analog?planet=mars&regionId=MARS-001&filter=rover")
	if err != nil {
		t.Fatal(err)
	}
	get := decode(t, resp)
	req := `{"misiones":{"filter":"rover"},"caracteristicas":{"planet":"mars","regionId":"MARS-001"}}`
	resp, err = http.Post(srv.URL+"/api/calculate", "application/json", strings.NewReader(req))
	if err != nil {
		t.Fatal(err)
	}
	post := decode(t, resp)
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("calculate: status %d: %v", resp.StatusCode, post)
	}
	g, _ := json.Marshal(get)
	p, _ := json.Marshal(post)
	if !bytes.Equal(g, p) {
		t.Error("POST /api/calculate and GET /api/analog differ")
	}
}

func TestEndpointsAvailable(t *testing.T) {
	srv := newTestServer(t, "", false)
	for _, path := range []string{"/api/status", "/api/catalog", "/api/regions?planet=mars", "/api/filters"} {
		resp, err := http.Get(srv.URL + path)
		if err != nil {
			t.Fatal(err)
		}
		resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Errorf("GET %s: status %d", path, resp.StatusCode)
		}
	}
	resp, err := http.Get(srv.URL + "/api/filters")
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	var reps []map[string]any
	if err := json.NewDecoder(resp.Body).Decode(&reps); err != nil || len(reps) != 4 {
		t.Fatalf("/api/filters: %v, %d missions", err, len(reps))
	}
}

func TestStatusImage(t *testing.T) {
	srv := newTestServer(t, "", false)
	resp, err := http.Get(srv.URL + "/api/status")
	if err != nil {
		t.Fatal(err)
	}
	img, _ := decode(t, resp)["image"].(string)
	resp, err = http.Get(srv.URL + img)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	var head [8]byte
	_, _ = resp.Body.Read(head[:])
	if resp.StatusCode != http.StatusOK || resp.Header.Get("Content-Type") != "image/png" || string(head[1:4]) != "PNG" {
		t.Errorf("GET %s: status %d, type %q", img, resp.StatusCode, resp.Header.Get("Content-Type"))
	}
}

// Router errors (unknown route, wrong method) are JSON like every other error.
func TestRouterErrorsAreJSON(t *testing.T) {
	srv := newTestServer(t, "", false)
	resp, err := http.Post(srv.URL+"/api/analog", "application/json", nil)
	if err != nil {
		t.Fatal(err)
	}
	if body := decode(t, resp); resp.StatusCode != http.StatusMethodNotAllowed || body["error"] == nil {
		t.Errorf("POST /api/analog: status %d, body %v", resp.StatusCode, body)
	}
	if resp.Header.Get("Allow") == "" {
		t.Error("405 without an Allow header")
	}
	resp, err = http.Get(srv.URL + "/api/nope")
	if err != nil {
		t.Fatal(err)
	}
	if body := decode(t, resp); resp.StatusCode != http.StatusNotFound || body["error"] == nil {
		t.Errorf("GET /api/nope: status %d, body %v", resp.StatusCode, body)
	}
}

func TestOwnRegionsFlag(t *testing.T) {
	off := newTestServer(t, "", false)
	on := newTestServer(t, "", true)
	for _, c := range []struct {
		srv  *httptest.Server
		want int
		own  bool
	}{{off, http.StatusForbidden, false}, {on, http.StatusOK, true}} {
		resp, err := http.Get(c.srv.URL + "/api/custom")
		if err != nil {
			t.Fatal(err)
		}
		decode(t, resp)
		if resp.StatusCode != c.want {
			t.Errorf("own-regions=%v: GET /api/custom status %d, want %d", c.own, resp.StatusCode, c.want)
		}
		resp, err = http.Get(c.srv.URL + "/api/catalog")
		if err != nil {
			t.Fatal(err)
		}
		caps := decode(t, resp)["capabilities"].(map[string]any)
		if caps["ownRegions"] != c.own {
			t.Errorf("own-regions=%v: catalog says %v", c.own, caps["ownRegions"])
		}
	}
}

func TestCORS(t *testing.T) {
	cases := []struct {
		allowed, origin string
		want            bool
	}{
		{"", "http://localhost:5173", true},
		{"", "http://127.0.0.1:3000", true},
		{"", "https://evil.example", false},
		{"https://app.example", "https://app.example", true},
		{"https://app.example", "http://localhost:5173", false},
	}
	for _, c := range cases {
		srv := newTestServer(t, c.allowed, false)
		req, _ := http.NewRequest(http.MethodOptions, srv.URL+"/api/calculate", nil)
		req.Header.Set("Origin", c.origin)
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			t.Fatal(err)
		}
		resp.Body.Close()
		if resp.StatusCode != http.StatusNoContent {
			t.Errorf("OPTIONS: status %d", resp.StatusCode)
		}
		got := resp.Header.Get("Access-Control-Allow-Origin") == c.origin
		if got != c.want {
			t.Errorf("allowed=%q origin=%q: allowed %v, want %v", c.allowed, c.origin, got, c.want)
		}
		if m := resp.Header.Get("Access-Control-Allow-Methods"); !strings.Contains(m, "POST") || !strings.Contains(m, "DELETE") {
			t.Errorf("Allow-Methods %q must include POST and DELETE", m)
		}
	}
}

func TestIsLoopback(t *testing.T) {
	for addr, want := range map[string]bool{
		"127.0.0.1:8080": true, "localhost:8080": true, "[::1]:8080": true,
		":8080": false, "0.0.0.0:8080": false, "192.168.1.5:8080": false,
	} {
		if isLoopback(addr) != want {
			t.Errorf("isLoopback(%q) != %v", addr, want)
		}
	}
}

