package API

import (
	"bytes"
	"encoding/json"
	"math"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"sync"
	"testing"

	"spaceapps/custom"
	"spaceapps/jsonParser"
)

func newServer(t *testing.T, own bool) http.Handler {
	t.Helper()
	p, err := jsonParser.New("../knn/testdata")
	if err != nil {
		t.Fatal(err)
	}
	s := &Server{Parser: p}
	if own {
		s.Custom = custom.NewStore()
	}
	return s.Routes()
}

func do(t *testing.T, h http.Handler, method, url string, body []byte) (*httptest.ResponseRecorder, map[string]any) {
	t.Helper()
	req := httptest.NewRequest(method, url, bytes.NewReader(body))
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	var out map[string]any
	if rec.Body.Len() > 0 {
		if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
			t.Fatalf("%s %s: invalid JSON response: %v\n%s", method, url, err, rec.Body.String())
		}
	}
	return rec, out
}

func readFile(t *testing.T, path string) []byte {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func matchIDs(resp map[string]any) []string {
	var ids []string
	for _, m := range resp["matches"].([]any) {
		ids = append(ids, m.(map[string]any)["regionId"].(string))
	}
	return ids
}

// Built-in behaviour is unchanged (same as knn/testdata/snapshot_real.json).
func TestBuiltinAnalogUnchanged(t *testing.T) {
	h := newServer(t, false)
	rec, resp := do(t, h, "GET", "/api/analog?planet=mars&regionId=MARS-001&filter=rover", nil)
	if rec.Code != 200 {
		t.Fatalf("status %d: %s", rec.Code, rec.Body)
	}
	want := []string{"EARTH-005", "EARTH-004", "EARTH-003"}
	if got := matchIDs(resp); strings.Join(got, ",") != strings.Join(want, ",") {
		t.Fatalf("got %v want %v", got, want)
	}
	// POST /api/calculate gives the same result.
	body := []byte(`{"misiones":{"filter":"rover"},"caracteristicas":{"planet":"mars","regionId":"MARS-001"}}`)
	rec, resp2 := do(t, h, "POST", "/api/calculate", body)
	if rec.Code != 200 || strings.Join(matchIDs(resp2), ",") != strings.Join(want, ",") {
		t.Fatalf("calculate: %d %v", rec.Code, matchIDs(resp2))
	}
}

